### Python
```python
if condition:
    import warnings
    warnings.warn("Warning: " + str(condition))
```

### C++ (Using STL)
```cpp
#include <iostream>
#include <string>
#include <warnings.h>  // From <cwts> for C++17

int main() {
    if (condition) {
        std::wcerr << "Warning: " << condition << std::endl;
        std::wcerr << "This is a warning message." << std::endl;
        std::wcerr.flush();
        std::warnings::warn("my_domain", "my_message", __FILE__, __LINE__);
        return 1;  // Exit with a non-zero status to indicate a warning
